def setrow(s, gid, text):
    rx = re.compile(r'^\| %s \| .*$' % re.escape(gid), re.M)
    if len(rx.findall(s)) != 1: raise SystemExit('ROW MISS ' + gid)
    return rx.sub(lambda m: '| %s | %s |' % (gid, text), s)
def sub1(s, old, new):
    if s.count(old) != 1: raise SystemExit('MISS (%d): %r' % (s.count(old), old[:90]))
    return s.replace(old, new)

